SQL_DOC.P_SQL:
DECLARE
V_COUNT NUMBER;
BEGIN SELECT COUNT(*) INTO V_COUNT FROM TBL_KEP_IV WHERE PLANT = $PLANT$ AND LEGACY_IV_NO = $LEGACY_IV_NO$ AND LEGACY_IV_SEQ = $LEGACY_IV_SEQ$ ;
IF V_COUNT = 0 THEN
INSERT INTO TBL_KEP_IV( PLANT , LEGACY_IV_NO , LEGACY_IV_SEQ , ZSTATUS , LEGACY_PO_NO , LEGACY_PO_SEQ , BUYER_ITEM_NO , ITEM_QTY , RD_DATE , IF_FLAG , IF_DATE , IF_TIME , PISTAT )VALUES( $PLANT$ , $LEGACY_IV_NO$ , $LEGACY_IV_SEQ$ , $STATUS$ , $LEGACY_PO_NO$ , $LEGACY_PO_SEQ$ , $BUYER_ITEM_NO$ , $INV_QTY$ , $INV_DATE$ , 'N' , TO_CHAR(SYSDATE,'YYYYMMDD') , TO_CHAR(SYSDATE,'HH24MISS') , 'R' ); ELSE UPDATE TBL_KEP_IV SET ZSTATUS = $STATUS$ , RD_DATE = $INV_DATE$ , IF_FLAG = 'N' , IF_DATE = TO_CHAR(SYSDATE,'YYYYMMDD') , IF_TIME = TO_CHAR(SYSDATE,'HH24MISS') , PISTAT = 'R' WHERE PLANT = $PLANT$ AND LEGACY_IV_NO = $LEGACY_IV_NO$ AND LEGACY_IV_SEQ = $LEGACY_IV_SEQ$ ; END IF; END;
